import com.cronutils.model.CronType;
import com.cronutils.model.definition.CronDefinition;
import com.cronutils.model.definition.CronDefinitionBuilder;
import com.cronutils.parser.CronParser;
import com.cronutils.model.Cron;
import com.cronutils.model.time.ExecutionTime;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import com.cronutils.model.field.constraint.CronConstraintsFactory;
import com.cronutils.model.field.expression.CronFieldExpression;

private static CronDefinition quartz() {
    return CronDefinitionBuilder.defineCron()
            .withSeconds().and()
            .withMinutes().and()
            .withHours().and()
            .withDayOfMonth()
                .withValidRange(1, 31) // Ensure day of month is between 1 and 31
                .supportsL().supportsW().supportsLW().supportsQuestionMark().and()
            .withMonth()
                .withValidRange(1, 12) // Ensure month is between 1 and 12
                .and()
            .withDayOfWeek()
                .withValidRange(1, 7) // Ensure day of week is between 1 and 7
                .withMondayDoWValue(2)
                .supportsHash().supportsL().supportsQuestionMark().and()
            .withYear()
                .withValidRange(1970, 2099) // Ensure valid range for year
                .optional().and()
            .withCronValidation(CronConstraintsFactory.ensureEitherDayOfWeekOrDayOfMonth())
            .instance();
}

